//! TF_DS_RESUME_ASSEMBLE (off by default): an exact-resume prepend assembles its rows and positions in one kernel -
//! replayCut's fresh residual and mixing-weight copyRows, tailRowsCopy's ring-segment restores and the position upload
//! run as tf_ds_resume_assemble_kernel: each output row takes both fields from the tail ring's slot (replay + i) %
//! window (i < pre, the restored prefix) or from fresh row first + i - pre, and writes its position on device. Pure:
//! no cuda import; the launcher is Ops.resumeAssemble and the call site prompt.zig's replayCut (its copyRows +
//! tailRowsCopy + upload sequence stays the fallback arm). A malformed switch refuses startup.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_RESUME_ASSEMBLE";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadResumeAssemble}!bool {
    return parse(text) orelse error.BadResumeAssemble;
}

/// Whether the one-launch arm covers this shape (the call site keeps replayCut's copies otherwise): 16-byte word
/// copies of both fields, every word-copied buffer 16-byte aligned. `addrs` is the tail ring's two halves (h then
/// p), the fresh rows' two, and the two outputs, in that order.
pub fn ok(on: bool, row_h: usize, row_p: usize, window: usize, addrs: [6]u64) bool {
    if (!on or window == 0 or row_h == 0 or row_p == 0 or row_h % 16 != 0 or row_p % 16 != 0) return false;
    for (addrs) |a| if (a % 16 != 0) return false;
    return true;
}

/// Where the assembled row `i`'s fields come from and its position: the tail ring's slot (replay + i) % window when
/// i < pre (the restored prefix; the wrap is in the slot) and fresh row first + i - pre otherwise.
pub const Src = struct { tail_slot: ?usize, fresh_row: ?usize, pos: i64 };

pub fn rowSource(i: usize, pre: usize, first: usize, window: usize, replay: usize) Src {
    const pos: i64 = @intCast(replay + i);
    if (i < pre) return .{ .tail_slot = (replay + i) % window, .fresh_row = null, .pos = pos };
    return .{ .tail_slot = null, .fresh_row = first + i - pre, .pos = pos };
}

/// The kernel's data movement on the host (its reference in the tests below): `n` output rows, each `row_h` residual
/// bytes and `row_p` mixing-weight bytes, from the tail ring (window rows a field, the weights window * row_h bytes
/// in) or the fresh rows (from row `first`), into out_h / out_p and pos; the positions are replay .. replay + n.
pub fn assemble(tail_h: []const u8, tail_p: []const u8, fresh_h: []const u8, fresh_p: []const u8, out_h: []u8, out_p: []u8, pos: []i64, row_h: usize, row_p: usize, window: usize, pre: usize, first: usize, n: usize, replay: usize) void {
    std.debug.assert(pre <= n and window > 0 and row_h > 0 and row_p > 0);
    for (0..n) |i| {
        const s = rowSource(i, pre, first, window, replay);
        const sh = if (s.tail_slot) |slot| tail_h[slot * row_h ..][0..row_h] else fresh_h[s.fresh_row.? * row_h ..][0..row_h];
        const sp = if (s.tail_slot) |slot| tail_p[slot * row_p ..][0..row_p] else fresh_p[s.fresh_row.? * row_p ..][0..row_p];
        @memcpy(out_h[i * row_h ..][0..row_h], sh);
        @memcpy(out_p[i * row_p ..][0..row_p], sp);
        pos[i] = s.pos;
    }
}

test "the switch parses its forms and nothing else" {
    try std.testing.expectEqual(false, parse(null).?);
    try std.testing.expectEqual(false, parse("").?);
    try std.testing.expectEqual(false, parse("0").?);
    try std.testing.expectEqual(true, parse("1").?);
    try std.testing.expectEqual(@as(?bool, null), parse("2"));
    try std.testing.expectEqual(@as(?bool, null), parse("on"));
    try std.testing.expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadResumeAssemble, fromText("2"));
}

test "the one-launch shape check: word copies and aligned buffers only" {
    const a = [_]u64{ 0x1000, 0x2000, 0x3000, 0x4000, 0x5000, 0x6000 };
    try std.testing.expect(ok(true, 40_960, 16, 128, a)); // the served shape (hc 4, hidden 5120)
    try std.testing.expect(ok(true, 16, 16, 4, a));
    try std.testing.expect(!ok(false, 40_960, 16, 128, a)); // the switch is part of the check
    try std.testing.expect(!ok(true, 40_960, 16, 0, a)); // no ring
    try std.testing.expect(!ok(true, 40_964, 16, 128, a)); // a residual row is not a whole number of words
    try std.testing.expect(!ok(true, 40_960, 4, 128, a)); // nor a mixing-weight row
    var bad = a;
    bad[3] += 4; // fresh_p off the word grid
    try std.testing.expect(!ok(true, 40_960, 16, 128, bad));
}

test "the assembled rows and positions equal today's copy sequence (wraparound and short-append layouts)" {
    // Today's replayCut sequence, written from its code as the tests' independent reference: the fresh rows copy to
    // out rows [pre, ...), the tail rows restore from the ring's one or two segments (tailRowsCopy's wrap split),
    // each field separately, and the positions fill on the host (the upload's bytes). Small rows; h0271 runs the
    // served ones through the kernel's own source.
    const Today = struct {
        fn restore(dst: []u8, ring: []const u8, window: usize, rb: usize, p0: usize, rows: usize) void {
            const slot = p0 % window;
            const n1 = @min(rows, window - slot);
            @memcpy(dst[0 .. n1 * rb], ring[slot * rb ..][0 .. n1 * rb]);
            if (rows > n1) @memcpy(dst[n1 * rb ..][0 .. (rows - n1) * rb], ring[0 .. (rows - n1) * rb]);
        }
        fn run(tail_h: []const u8, tail_p: []const u8, fresh_h: []const u8, fresh_p: []const u8, out_h: []u8, out_p: []u8, pos: []i64, row_h: usize, row_p: usize, window: usize, pre: usize, first: usize, n: usize, replay: usize) void {
            const kept = n - pre;
            @memcpy(out_h[pre * row_h ..][0 .. kept * row_h], fresh_h[first * row_h ..][0 .. kept * row_h]);
            if (pre > 0) restore(out_h, tail_h, window, row_h, replay, pre);
            @memcpy(out_p[pre * row_p ..][0 .. kept * row_p], fresh_p[first * row_p ..][0 .. kept * row_p]);
            if (pre > 0) restore(out_p, tail_p, window, row_p, replay, pre);
            for (pos[0..n], 0..) |*p, i| p.* = @intCast(replay + i);
        }
    };
    const row_h = 48; // hc 1 of a 24-wide hidden, still whole words
    const row_p = 16; // the served mixing-weight row (hc 4)
    var cases: usize = 0;
    for ([_]usize{ 4, 128 }) |window| { // 128 the served ring; 4 a dense-wrap stress
        for ([_]usize{ 1, 2, 3, 5, 7, 8, 31, 63, 64, 65, 127, 128 }) |pre| {
            if (pre > window) continue;
            for ([_]usize{ 1, 2, 3, 4, 5, 6, 7, 16, 128, 300 }) |kept| { // 1..7 the served short appends
                for ([_]usize{ 0, 1, 4 }) |first| {
                    for ([_]usize{ 0, 1, window / 2, window - pre, window - 1 }) |mod| { // window - pre touches the wrap boundary; window - 1 wraps for pre >= 2
                        const replay = 7 * window + mod;
                        const n = pre + kept;
                        const n0 = first + kept;
                        const tail_h = try std.testing.allocator.alloc(u8, window * row_h);
                        defer std.testing.allocator.free(tail_h);
                        const tail_p = try std.testing.allocator.alloc(u8, window * row_p);
                        defer std.testing.allocator.free(tail_p);
                        const fresh_h = try std.testing.allocator.alloc(u8, n0 * row_h);
                        defer std.testing.allocator.free(fresh_h);
                        const fresh_p = try std.testing.allocator.alloc(u8, n0 * row_p);
                        defer std.testing.allocator.free(fresh_p);
                        const out_h = try std.testing.allocator.alloc(u8, n * row_h);
                        defer std.testing.allocator.free(out_h);
                        const out_p = try std.testing.allocator.alloc(u8, n * row_p);
                        defer std.testing.allocator.free(out_p);
                        const want_h = try std.testing.allocator.alloc(u8, n * row_h);
                        defer std.testing.allocator.free(want_h);
                        const want_p = try std.testing.allocator.alloc(u8, n * row_p);
                        defer std.testing.allocator.free(want_p);
                        const pos = try std.testing.allocator.alloc(i64, n);
                        defer std.testing.allocator.free(pos);
                        const want_pos = try std.testing.allocator.alloc(i64, n);
                        defer std.testing.allocator.free(want_pos);
                        // distinct bytes per ring slot and per fresh row, so a wrong source row cannot pass
                        for (0..window) |s| {
                            for (0..row_h) |j| tail_h[s * row_h + j] = @intCast((s * 31 + j * 7 + 1) & 0xff);
                            for (0..row_p) |j| tail_p[s * row_p + j] = @intCast((s * 17 + j * 13 + 2) & 0xff);
                        }
                        for (0..n0) |r| {
                            for (0..row_h) |j| fresh_h[r * row_h + j] = @intCast((r * 53 + j * 11 + 3) & 0xff);
                            for (0..row_p) |j| fresh_p[r * row_p + j] = @intCast((r * 41 + j * 19 + 4) & 0xff);
                        }
                        @memset(out_h, 0xAA);
                        @memset(out_p, 0xAA);
                        Today.run(tail_h, tail_p, fresh_h, fresh_p, want_h, want_p, want_pos, row_h, row_p, window, pre, first, n, replay);
                        assemble(tail_h, tail_p, fresh_h, fresh_p, out_h, out_p, pos, row_h, row_p, window, pre, first, n, replay);
                        try std.testing.expectEqualSlices(u8, want_h, out_h);
                        try std.testing.expectEqualSlices(u8, want_p, out_p);
                        try std.testing.expectEqualSlices(i64, want_pos, pos);
                        cases += 1;
                    }
                }
            }
        }
    }
    try std.testing.expect(cases >= 150);
}

