//! The torch operations of the served forward that only move or widen bytes, on TensorFold's own torch-op kernels
//! (zig/kernels/cuda/torch_ops: pointwise.cu, movement.cu; ours in dsv41_ops.cu) with their development launchers'
//! geometry: `.float()` of bf16 and fp16 (exact), `.to(bf16)` of fp32 (round to nearest even), `.contiguous()` and row
//! copies, row gathers and scatters by index (`t[idx]`, `t[idx] = rows`), and the integer selections of the indexer
//! (torch's top-k of int64 keys, kernels.topk_indices). Their bytes are the same as torch's by construction; the layer
//! gate checks them.
const std = @import("std");
const cuda = @import("cuda");
const expert_prune = @import("expert_prune.zig");
const idx_fused = @import("idx_fused.zig");
const fused_trace = @import("fused_trace.zig");
const compress2_norm = @import("compress2_norm.zig");
const rope_store = @import("rope_store.zig");
const conf_pack = @import("conf_pack.zig");
const topk_merge = @import("topk_merge.zig");
const resume_assemble = @import("resume_assemble.zig");

/// launch_shape.h's tf_launch_blocks: a block a `threads` elements, at most 65535.
fn blocks(count: usize, threads: usize) u32 {
    return @intCast(@min((count + threads - 1) / threads, 65535));
}

/// The switch for the drafter's keyed noise (tf_ds_keyed_noise_kernel); read at load on every rank.
pub const keyed_env = "TF_DS_T26_KEYED_DRAFT";

/// One stream's row of tf_ds_keyed_noise_kernel's table: the sampler's seed and temperature, and the absolute position
/// of its step-0 draft.
pub const KeyedRow = extern struct { seed: u64, temp: f64, pos: i64 };

/// TF_DS_T26_KEYED_DRAFT's and TF_DS_T27_DEVICE_DRAW's parse: on only for exactly "1" (unset, "0", "", "on" or
/// anything else: off).
pub fn isOne(v: ?[]const u8) bool {
    const s = v orelse return false;
    return std.mem.eql(u8, s, "1");
}

fn envOn(name: [:0]const u8) bool {
    return isOne(envSpan(name));
}

/// The switch for speculative sampling of a sampled stream (lanes.zig's accept rule over tf_ds_spec_clean_kernel's
/// proposal and tf_ds_gather_cols_kernel's verify gather); read at load on every rank.
pub const spec_env = "TF_DS_SPEC_SAMPLE";

/// The switch for programmatic dependent launches (the hand-written kernels wait for the one before and let the next
/// one launch; launch-timing only, bits identical); read at load on every rank. Not TF_RDMA_PDL / TF_DS_TRITON_PDL.
pub const pdl_env = "TF_DS_PDL";

/// The switch for the indexer's top-k in three reads of the row instead of ten (tf_ds_topk_indices_fast_kernel: a
/// sampled threshold, one compacting pass, the exact k-th among the candidates, the eight-digit select as the
/// fallback); read at load on every rank, bits identical either way (the same k keys, the same order).
pub const topk_fast_env = "TF_DS_TOPK_FAST";

/// TF_DS_CHECK_INVALID (off by default): read the ratio-2 compressor's out-of-range-partner flag back once a chain and
/// log an error when it is set, and check on the host that a round's rows name distinct raw ring slots (the fused
/// scatter's in-kernel assumption). The flag is written by the unfused gatherRows path and by 0127's and 0197's
/// compressors; the fused chains do not clear it, so a set flag also latches. Diagnostic only: no kernel changes, and an
/// unset switch costs nothing (no read, no sync). Read at load on every rank.
pub const check_invalid_env = "TF_DS_CHECK_INVALID";

/// The series' switches' parse ("1" or "on"; unset, "0", "off", "" or anything else: off).
pub fn onValue(v: ?[]const u8) bool {
    const s = v orelse return false;
    return std.mem.eql(u8, s, "1") or std.mem.eql(u8, s, "on");
}

/// TF_DS_SPEC_SAMPLE's parse (the series' switches: "1" or "on"; unset, "0", "off", "" or anything else: off), and the
/// one combination refused: TF_DS_T26_KEYED_DRAFT on as ops reads it (exactly "1") with this one. Both put Gumbel noise
/// on the drafter's logits with different keys (T26 the sampler's own, so a draft lands only when it equals the target's
/// draw; this one an independent draft key, which the accept rule needs), so one pass cannot run both.
pub fn specSample(v: ?[]const u8, keyed: ?[]const u8) !bool {
    const on = onValue(v);
    if (on and isOne(keyed)) return error.SpecAndKeyedDraft;
    return on;
}

/// The message both ranks log when they refuse the pair (native.explain gives it to rank 0's start too).
pub const spec_keyed_why = "TF_DS_SPEC_SAMPLE and TF_DS_T26_KEYED_DRAFT=1 cannot run together (both put keyed noise on the drafter's logits, with different keys): set TF_DS_T26_KEYED_DRAFT=0 (any value but 1, or unset) on both ranks to run TF_DS_SPEC_SAMPLE, or unset TF_DS_SPEC_SAMPLE";

/// TF_DS_SPEC_SAMPLE: tf_ds_spec_clean_kernel's blocks a row (its grid.x), so a row's normaliser partials are
/// 2 * spec_parts floats after its clean scores.
pub const spec_parts = 16;

fn envSpan(name: [:0]const u8) ?[]const u8 {
    return if (std.c.getenv(name)) |p| std.mem.span(p) else null;
}

/// The switch for the device draw of sampled rows (tf_ds_draw_rows_kernel); read at load on every rank.
pub const draw_env = "TF_DS_T27_DEVICE_DRAW";

/// The switch for a runtime LoRA adapter on the DSpark drafter (lora.zig); a folder, so any non-empty value is on.
pub const lora_env = "TF_DS_LORA";

fn loraOn() bool {
    const v = std.c.getenv(lora_env) orelse return false;
    return std.mem.span(v).len > 0;
}

/// One row of tf_ds_draw_rows_kernel's rule table: the sampler's seed, temperature, top_p, min_p, the row's absolute
/// position and top_k (1..56 when temp > 0; the host keeps other rules off the kernel).
pub const DrawRow = extern struct { seed: u64, temp: f64, top_p: f64, min_p: f64, pos: u64, top_k: u32, pad: u32 = 0 };

/// tf_ds_l2_prefetch_kernel's argument: up to 16 device ranges (their first byte and length).
pub const Prefetch = extern struct { ptr: [16]u64 = @splat(0), bytes: [16]u64 = @splat(0), n: c_int = 0 };

pub const Ops = struct {
    pointwise: cuda.Module,
    movement: cuda.Module,
    family: cuda.Module,
    to_f32: cuda.Function,
    f16_to_f32: cuda.Function,
    add2_bf16: cuda.Function,
    topk_i64: cuda.Function,
    topk_indices: cuda.Function,
    topk_indices_fast: cuda.Function, // TF_DS_TOPK_FAST (launched only under it)
    scatter: cuda.Function,
    cand_fast: cuda.Function,
    cand_fast8: ?cuda.Function = null,
    iota_vis: cuda.Function,
    l2_prefetch: cuda.Function,

