    pub fn unload(o: *Ops) void {
        o.pointwise.unload();
        o.movement.unload();
        o.family.unload();
        o.* = undefined;
    }

    fn go(o: *const Ops, f: cuda.Function, s: cuda.Stream, grid: usize, block: u32, args: *cuda.Args) !void {
        try cuda.launch.launch(f, .{ .grid = .{ .x = @intCast(grid) }, .block = .{ .x = block }, .pdl = o.pdl }, s, args);
    }

    /// `.float()` of `count` bf16 values (exact).
    pub fn toF32(o: *const Ops, s: cuda.Stream, in: u64, out: u64, count: usize) !void {
        if (count == 0) return;
        var a: cuda.Args = .{};
        a.add(in);
        a.add(out);
        a.add(@as(u64, count));
        a.add(@as(c_int, @intFromBool(o.pdl)));
        try go(o, o.to_f32, s, blocks(count, 256), 256, &a);
    }

    /// `.float()` of `count` fp16 values (exact).
    pub fn f16ToF32(o: *const Ops, s: cuda.Stream, in: u64, out: u64, count: usize) !void {
        if (count == 0) return;
        var a: cuda.Args = .{};
        a.add(in);
        a.add(out);
        a.add(@as(u64, count));
        a.add(@as(c_int, @intFromBool(o.pdl)));
        try go(o, o.f16_to_f32, s, blocks(count, 256), 256, &a);
    }

    /// Comm.sum of two ranks' fp32 partials then `.to(bf16)`: out = bf16(g0 + g1), one fp32 add in rank order.
    pub fn add2Bf16(o: *const Ops, s: cuda.Stream, g0: u64, g1: u64, out: u64, count: usize) !void {
        if (count == 0) return;
        var a: cuda.Args = .{};
        a.add(g0);
        a.add(g1);
        a.add(out);
        a.add(@as(u64, count));
        a.add(@as(c_int, @intFromBool(o.pdl)));
        try go(o, o.add2_bf16, s, blocks(count, 256), 256, &a);
    }

    /// x + y of bf16 values in place on x (torch's add: fp32 sum, rounded once; tf_ds_add_bf16_kernel). TF_DS_LORA's
    /// epilogue adds its term with it.
    pub fn addBf16(o: *const Ops, s: cuda.Stream, x: u64, y: u64, count: usize) !void {
        if (count == 0) return;
        const f = o.lora_add orelse return error.AdapterAddUnavailable;
        var a: cuda.Args = .{};
        a.add(x);
        a.add(y);
        a.add(@as(u64, count));
        a.add(@as(c_int, @intFromBool(o.pdl)));
        try go(o, f, s, blocks(count, 256), 256, &a);
