            var w: cuda.Args = .{};
            w.add(src);
            w.add(@as(u64, src_ld / 16));
            w.add(dst);
            w.add(@as(u64, dst_ld / 16));
            w.add(@as(u64, bytes / 16));
            w.add(@as(c_int, @intFromBool(o.pdl)));
            return cuda.launch.launch(o.copy16, .{ .grid = .{ .x = blocks(bytes / 16, 256), .y = @intCast(rows) }, .block = .{ .x = 256 }, .pdl = o.pdl }, s, &w);
        }
